ControlPropertyState.AutoRuleBindingString:
With(
    {
        _key: Lower(Trim(Self.SelectedItemKey)),
        _hasProject: !IsBlank(varProjectId),
        _hasConfig: varProjectHasReportConfig || varHomeHiveLoaded || varProjectHasPHRData
    },

    If(
        _key = "superadmin",

        Set(varGlobalLoading, false);
        Set(varGlobalLoadingMsg, "");
        Set(varGlobalLoadingSubMsg, "");
        Set(varGlobalLoadingScope, "");
        Set(varGlobalLoadAction, "");
        Set(varGlobalLoadPending, false);

        Set(varPHR_IsLoading, false);
        Set(varOps_IsLoading, false);
        Set(varTasks_IsLoading, false);
        Set(varPunches_IsLoading, false);
        Set(varCfg_IsLoading, false);

        Set(varAppView, "SuperAdmin");
        Set(varPageKey, "SUPERADMIN");
        Set(varPageTitle, "Administration");
        Set(varPageSubtitle, "Platform configuration and governance");

        Navigate(scr_SuperAdmin, ScreenTransition.None),

        If(
            _key <> "home" && !_hasProject,

            Notify("Please select a project first.", NotificationType.Warning);

            Set(varAppView, "Home");
            Set(varPageKey, "HOME");
            Set(varPageTitle, "Home");
            Set(varPageSubtitle, "Project command center");

            Navigate(scr_Home, ScreenTransition.None),

            If(
                _key in ["overview", "tasks", "punches", "briefing", "config", "skyline"] && !_hasConfig,

                Notify(
                    "This project has no published report configuration yet.",
                    NotificationType.Warning
                );

                Set(varAppView, "Home");
                Set(varPageKey, "HOME");
                Set(varPageTitle, "Home");
                Set(varPageSubtitle, "Project command center");

                Navigate(scr_Home, ScreenTransition.None),

                Switch(
                    _key,

                    "skyline",
                        Set(varAppView, "Skyline");
                        Set(varPageKey, "SKYLINE");
                        Set(varPageTitle, "Delivery Skyline");
                        Set(varPageSubtitle, "Weekly subsystem delivery risk and workload forecast");
                        Navigate(scr_Skyline, ScreenTransition.None),

                    "home",
                        Set(varGlobalLoading, false);
                        Set(varGlobalLoadingMsg, "");
                        Set(varGlobalLoadingSubMsg, "");
                        Set(varGlobalLoadingScope, "");
                        Set(varGlobalLoadAction, "");
                        Set(varGlobalLoadPending, false);

                        Set(varPHR_IsLoading, false);
                        Set(varOps_IsLoading, false);
                        Set(varTasks_IsLoading, false);
                        Set(varPunches_IsLoading, false);
                        Set(varCfg_IsLoading, false);

                        Set(varAppView, "Home");
                        Set(varPageKey, "HOME");
                        Set(varPageTitle, "Home");
                        Set(varPageSubtitle, "Project command center");
                        Set(varHomeViewMode, "DASHBOARD");

                        Navigate(scr_Home, ScreenTransition.None),

                    "overview",
                        Set(varAppView, "Overview");
                        Set(varPageKey, "OVERVIEW");
                        Set(varPageTitle, "Overview");
                        Set(varPageSubtitle, "Project Handover Report by subsystem, discipline and form family");
                        Set(varOps_ViewMode, "OVERVIEW");

                        Navigate(scr_Overview, ScreenTransition.None),

                    "tasks",
                        Set(varAppView, "Tasks");
                        Set(varPageKey, "TASKS");
                        Set(varPageTitle, "Tasks");
                        Set(varPageSubtitle, "Inspection task management");

                        Navigate(scr_Tasks, ScreenTransition.None),

                    "punches",
                        Set(varAppView, "Punches");
                        Set(varPageKey, "PUNCHES");
                        Set(varPageTitle, "Punch List");
                        Set(varPageSubtitle, "Punch item management");

                        Navigate(scr_Punches, ScreenTransition.None),

                    "briefing",
                        Set(varAppView, "Briefing");
                        Set(varPageKey, "BRIEFING");
                        Set(varPageTitle, "Briefing");
                        Set(varPageSubtitle, "Project reporting and communication");

                        Navigate(scr_Briefing, ScreenTransition.None),

                    "config",
                        Set(varAppView, "Config");
                        Set(varPageKey, "CONFIG");
                        Set(varPageTitle, "Configuration");
                        Set(varPageSubtitle, "Report structure and scope management");

                        Navigate(scr_Config, ScreenTransition.None),

                    Notify("Key not mapped: [" & _key & "]", NotificationType.Error)
                )
            )
        )
    )
)
